{"action":"create","artifactId":"concept-flow","title":"Concept flow map","source":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Concept flow map</title>
  <style>
:root {
  color-scheme: light dark;
  --art-bg: #f5f7fb;
  --art-surface: rgba(255, 255, 255, 0.92);
  --art-surface-raised: #ffffff;
  --art-ink: #17202b;
  --art-muted: #647184;
  --art-accent: #5b5bd6;
  --art-accent-strong: #4343b8;
  --art-accent-soft: rgba(91, 91, 214, 0.13);
  --art-good: #16805c;
  --art-good-soft: rgba(22, 128, 92, 0.11);
  --art-warn: #a86500;
  --art-warn-soft: rgba(168, 101, 0, 0.12);
  --art-bad: #b84955;
  --art-bad-soft: rgba(184, 73, 85, 0.11);
  --art-border: rgba(68, 83, 112, 0.14);
  --art-grid: rgba(82, 96, 128, 0.07);
  --art-radius: 20px;
  --art-radius-sm: 12px;
  --art-shadow: 0 18px 50px rgba(36, 47, 72, 0.09);
  --art-font: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

@media (prefers-color-scheme: dark) {
  :root {
    --art-bg: #11151d;
    --art-surface: rgba(25, 31, 42, 0.94);
    --art-surface-raised: #1d2532;
    --art-ink: #edf2fb;
    --art-muted: #a1aec2;
    --art-accent: #9b9bf7;
    --art-accent-strong: #b7b7ff;
    --art-accent-soft: rgba(155, 155, 247, 0.16);
    --art-good: #62d5a8;
    --art-good-soft: rgba(98, 213, 168, 0.13);
    --art-warn: #f1bc65;
    --art-warn-soft: rgba(241, 188, 101, 0.14);
    --art-bad: #f38a96;
    --art-bad-soft: rgba(243, 138, 150, 0.14);
    --art-border: rgba(184, 202, 232, 0.14);
    --art-grid: rgba(185, 202, 231, 0.08);
    --art-shadow: 0 20px 60px rgba(0, 0, 0, 0.28);
  }
}

* { box-sizing: border-box; }
html { background: var(--art-bg); }
body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background:
    radial-gradient(circle at 8% 0%, var(--art-accent-soft), transparent 34rem),
    radial-gradient(circle at 96% 96%, var(--art-good-soft), transparent 30rem),
    var(--art-bg);
  color: var(--art-ink);
  font-family: var(--art-font);
  font-size: 14px;
  line-height: 1.5;
}
button, select, input { font: inherit; }
button, select { color: var(--art-ink); }
button { cursor: pointer; }
button:disabled { cursor: not-allowed; opacity: 0.58; }
button:focus-visible, select:focus-visible, input:focus-visible {
  outline: 3px solid var(--art-accent-soft);
  outline-offset: 2px;
}
.lab {
  width: min(1100px, 100%);
  margin: 0 auto;
  padding: 28px;
  display: grid;
  gap: 18px;
}
.hero {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(180px, 0.6fr);
  gap: 18px;
  align-items: end;
}
.eyebrow {
  margin: 0 0 7px;
  color: var(--art-accent);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}
h1, h2, h3, p { margin-top: 0; }
h1 {
  margin-bottom: 8px;
  font-size: clamp(28px, 4vw, 40px);
  line-height: 1.08;
  letter-spacing: -0.04em;
}
h2 { margin-bottom: 0; font-size: 16px; letter-spacing: -0.01em; }
.subtitle { margin-bottom: 0; max-width: 62ch; color: var(--art-muted); line-height: 1.65; }
.pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  width: fit-content;
  padding: 7px 11px;
  border: 1px solid var(--art-border);
  border-radius: 999px;
  background: var(--art-surface);
  color: var(--art-muted);
  font-size: 12px;
  white-space: nowrap;
}
.pill::before { content: ''; width: 7px; height: 7px; border-radius: 50%; background: var(--art-accent); }
.workspace { display: grid; grid-template-columns: minmax(0, 1.55fr) minmax(250px, 0.75fr); gap: 16px; align-items: stretch; }
.stage, .panel, .timeline {
  border: 1px solid var(--art-border);
  border-radius: var(--art-radius);
  background: var(--art-surface);
  box-shadow: var(--art-shadow);
  backdrop-filter: blur(14px);
}
.stage { position: relative; min-height: 330px; padding: 22px; overflow: hidden; }
.stage::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
  background-image: linear-gradient(var(--art-grid) 1px, transparent 1px), linear-gradient(90deg, var(--art-grid) 1px, transparent 1px);
  background-size: 28px 28px;
  mask-image: linear-gradient(to bottom, black, transparent 88%);
}
.panel { padding: 18px; display: grid; gap: 14px; align-content: start; }
.panel h2 { margin-bottom: 2px; }
.field { display: grid; gap: 7px; }
.field label, .field-label { color: var(--art-muted); font-size: 12px; font-weight: 650; }
select, input[type='range'] {
  width: 100%;
  min-height: 42px;
  border: 1px solid var(--art-border);
  border-radius: var(--art-radius-sm);
  background: var(--art-surface-raised);
  padding: 9px 11px;
}
input[type='range'] { padding: 0; accent-color: var(--art-accent); }
.button-row { display: flex; flex-wrap: wrap; gap: 8px; }
button {
  min-height: 40px;
  padding: 9px 13px;
  border: 1px solid var(--art-border);
  border-radius: var(--art-radius-sm);
  background: var(--art-surface-raised);
  color: var(--art-ink);
  font-weight: 650;
  transition: transform 160ms ease, border-color 160ms ease, background 160ms ease, box-shadow 160ms ease;
}
button:hover:not(:disabled) { transform: translateY(-1px); border-color: var(--art-accent); box-shadow: 0 7px 18px var(--art-accent-soft); }
button:active:not(:disabled) { transform: translateY(0); }
button[data-active='true'], button.primary {
  border-color: transparent;
  background: var(--art-accent);
  color: #fff;
}
button[data-active='true']:hover, button.primary:hover { background: var(--art-accent-strong); }
.metric-row { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 9px; }
.metric { padding: 12px; border: 1px solid var(--art-border); border-radius: var(--art-radius-sm); background: var(--art-surface-raised); }
.metric strong { display: block; margin-bottom: 3px; font-size: 20px; letter-spacing: -0.02em; }
.metric span { color: var(--art-muted); font-size: 11px; }
.result {
  min-height: 54px;
  padding: 13px 14px;
  border: 1px solid var(--art-border);
  border-radius: var(--art-radius-sm);
  background: var(--art-surface-raised);
  color: var(--art-muted);
}
.result[data-tone='good'] { border-color: transparent; background: var(--art-good-soft); color: var(--art-good); }
.result[data-tone='warn'] { border-color: transparent; background: var(--art-warn-soft); color: var(--art-warn); }
.result[data-tone='bad'] { border-color: transparent; background: var(--art-bad-soft); color: var(--art-bad); }
.feedback {
  padding: 14px 16px;
  border-left: 3px solid var(--art-good);
  border-radius: var(--art-radius-sm);
  background: var(--art-good-soft);
  color: var(--art-good);
  font-weight: 650;
}
.timeline { padding: 16px 18px; display: flex; flex-wrap: wrap; gap: 14px; align-items: center; }
.step { display: inline-flex; align-items: center; gap: 7px; color: var(--art-muted); font-size: 12px; }
.step::before { content: ''; width: 8px; height: 8px; border: 1px solid var(--art-muted); border-radius: 50%; }
.step[data-state='done'] { color: var(--art-good); }
.step[data-state='done']::before { border-color: var(--art-good); background: var(--art-good); }
.step[data-state='current'] { color: var(--art-accent); }
.step[data-state='current']::before { border-color: var(--art-accent); background: var(--art-accent); box-shadow: 0 0 0 4px var(--art-accent-soft); }
.chart { display: block; width: 100%; height: 230px; border-radius: var(--art-radius-sm); background: var(--art-surface-raised); }
.motion-enter { animation: art-enter 420ms cubic-bezier(0.2, 0.8, 0.2, 1) both; }
.motion-highlight { animation: art-highlight 560ms cubic-bezier(0.2, 0.8, 0.2, 1); }
@keyframes art-enter { from { opacity: 0; transform: translateY(9px); } to { opacity: 1; transform: translateY(0); } }
@keyframes art-highlight { 0% { box-shadow: 0 0 0 0 var(--art-accent-soft); } 45% { box-shadow: 0 0 0 8px var(--art-accent-soft); } 100% { box-shadow: 0 0 0 0 var(--art-accent-soft); } }
@media (max-width: 780px) {
  .lab { padding: 18px; }
  .hero, .workspace { grid-template-columns: 1fr; }
  .stage { min-height: 290px; }
  .metric-row { grid-template-columns: 1fr; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 1ms !important; transition-duration: 1ms !important; scroll-behavior: auto !important; }
}

</style>
</head>
<body>
  <main class="lab">
    <header class="hero">
      <div>
        <p class="eyebrow">Concept map</p>
        <h1>Concept flow map</h1>
        <p class="subtitle">Trace an explanation as a living process. Select a concept, advance the flow, and inspect how each step connects.</p>
      </div>
      <span class="pill">SceneSpec</span>
    </header>

    <section class="workspace" aria-label="Concept flow workspace">
      <div class="stage">
        <div class="metric-row" aria-label="Current flow state">
          <div class="metric"><strong id="selected-value">Observe</strong><span>Selected concept</span></div>
          <div class="metric"><strong id="step-value">1 / 6</strong><span>Flow step</span></div>
          <div class="metric"><strong id="zoom-value">1.00×</strong><span>Viewport scale</span></div>
        </div>
        <svg id="flow" class="chart" viewBox="0 0 640 300" role="img" aria-label="Interactive concept flow map"></svg>
        <output id="readout" class="result" role="status" aria-live="polite">Select a concept to inspect its role.</output>
      </div>

      <aside class="panel" aria-label="Flow controls">
        <h2>Controls</h2>
        <div class="field">
          <label for="selected">Selected concept</label>
          <select id="selected"></select>
        </div>
        <div class="button-row">
          <button id="zoom-out" type="button" aria-label="Zoom out">−</button>
          <button id="zoom-in" type="button" aria-label="Zoom in">+</button>
          <button id="view-reset" type="button">Reset view</button>
        </div>
        <div class="button-row">
          <button id="play" class="primary" type="button">Play flow</button>
          <button id="step" type="button">Step</button>
          <button id="reset" type="button">Reset</button>
        </div>
        <button id="confirm" type="button">Confirm map</button>
        <p class="subtitle">Click a node or use the selector. The active path follows the current step without changing the underlying graph.</p>
      </aside>
    </section>

    <footer class="timeline">
      <span class="step">Observe</span>
      <span class="step">Predict</span>
      <span class="step">Manipulate</span>
      <span class="step">Feedback</span>
      <span class="step">Compare</span>
      <span class="step">Explain</span>
    </footer>
  </main>

  <script>
/* Small, one-shot motion primitives. Inline this file into an Artifact; no imports. */
function reducedMotion() {
  return window.matchMedia('(prefers-reduced-motion: reduce)').matches
}

function beat(elements, { staggerMs = 70 } = {}) {
  const list = Array.from(elements)
  if (reducedMotion()) {
    for (const element of list) element.dataset.beat = 'done'
    return
  }
  for (const [index, element] of list.entries()) {
    element.classList.add('motion-enter')
    element.style.animationDelay = `${index * staggerMs}ms`
    element.addEventListener('animationend', () => { element.dataset.beat = 'done' }, { once: true })
  }
}

function highlight(element) {
  if (!element) return
  if (reducedMotion()) return
  element.classList.remove('motion-highlight')
  void element.offsetWidth
  element.classList.add('motion-highlight')
}

function tween({ from, to, duration = 420, update, done }) {
  if (reducedMotion()) {
    update(to)
    done?.()
    return () => {}
  }
  const start = performance.now()
  let frame = 0
  const step = (now) => {
    const progress = Math.min(1, (now - start) / duration)
    const eased = 1 - Math.pow(1 - progress, 3)
    update(from + (to - from) * eased)
    if (progress < 1) frame = requestAnimationFrame(step)
    else done?.()
  }
  frame = requestAnimationFrame(step)
  return () => cancelAnimationFrame(frame)
}

</script>
  <script>
    const sceneSpec = {
      kind: 'flowchart',
      nodes: [
        { id: 'observe', label: 'Observe', x: 90, y: 70, tone: 'accent' },
        { id: 'predict', label: 'Predict', x: 320, y: 70, tone: 'accent' },
        { id: 'manipulate', label: 'Manipulate', x: 550, y: 70, tone: 'warn' },
        { id: 'feedback', label: 'Feedback', x: 550, y: 225, tone: 'good' },
        { id: 'compare', label: 'Compare', x: 320, y: 225, tone: 'good' },
        { id: 'explain', label: 'Explain', x: 90, y: 225, tone: 'muted' },
      ],
      edges: [
        { from: 'observe', to: 'predict' },
        { from: 'predict', to: 'manipulate' },
        { from: 'manipulate', to: 'feedback' },
        { from: 'feedback', to: 'compare' },
        { from: 'compare', to: 'explain' },
        { from: 'explain', to: 'observe' },
        { from: 'compare', to: 'predict', label: 'revise' },
      ],
      steps: ['observe', 'predict', 'manipulate', 'feedback', 'compare', 'explain'],
      viewport: { centerX: 0, centerY: 0, scale: 1 },
      selected: 'observe',
    }

    const svg = document.getElementById('flow')
    const readout = document.getElementById('readout')
    const selectedInput = document.getElementById('selected')
    const playButton = document.getElementById('play')
    const nodes = new Map(sceneSpec.nodes.map(node => [node.id, node]))
    let selected = sceneSpec.selected
    let currentIndex = 0
    let scale = sceneSpec.viewport.scale
    let centerX = sceneSpec.viewport.centerX
    let centerY = sceneSpec.viewport.centerY
    let playing = false
    let frame = 0
    let previous = 0
    let dragging = false
    let dragX = 0
    let dragY = 0

    for (const node of sceneSpec.nodes) {
      const option = document.createElement('option')
      option.value = node.id
      option.textContent = node.label
      selectedInput.appendChild(option)
    }
    selectedInput.value = selected

    function color(name, fallback) {
      return getComputedStyle(document.documentElement).getPropertyValue(name).trim() || fallback
    }

    function render() {
      const ink = color('--art-ink', '#17202b')
      const muted = color('--art-muted', '#647184')
      const accent = color('--art-accent', '#5b5bd6')
      const accentSoft = color('--art-accent-soft', 'rgba(91,91,214,.13)')
      const good = color('--art-good', '#16805c')
      const border = color('--art-border', 'rgba(68,83,112,.14)')
      const surface = color('--art-surface-raised', '#fff')
      const viewWidth = 640 / scale
      const viewHeight = 300 / scale
      svg.setAttribute('viewBox', `${320 - centerX - viewWidth / 2} ${150 - centerY - viewHeight / 2} ${viewWidth} ${viewHeight}`)
      svg.innerHTML = ''

      const defs = document.createElementNS('http://www.w3.org/2000/svg', 'defs')
      const marker = document.createElementNS('http://www.w3.org/2000/svg', 'marker')
      marker.setAttribute('id', 'arrow')
      marker.setAttribute('markerWidth', '8')
      marker.setAttribute('markerHeight', '8')
      marker.setAttribute('refX', '7')
      marker.setAttribute('refY', '3')
      marker.setAttribute('orient', 'auto')
      const arrow = document.createElementNS('http://www.w3.org/2000/svg', 'path')
      arrow.setAttribute('d', 'M0,0 L0,6 L7,3 z')
      arrow.setAttribute('fill', accent)
      marker.appendChild(arrow)
      defs.appendChild(marker)
      svg.appendChild(defs)

      for (const edge of sceneSpec.edges) {
        const from = nodes.get(edge.from)
        const to = nodes.get(edge.to)
        if (!from || !to) continue
        const active = selected === edge.from || selected === edge.to
        const line = document.createElementNS('http://www.w3.org/2000/svg', 'line')
        line.setAttribute('x1', String(from.x))
        line.setAttribute('y1', String(from.y))
        line.setAttribute('x2', String(to.x))
        line.setAttribute('y2', String(to.y))
        line.setAttribute('stroke', active ? accent : muted)
        line.setAttribute('stroke-width', active ? '3' : '1.5')
        line.setAttribute('opacity', active ? '1' : '0.48')
        line.setAttribute('marker-end', 'url(#arrow)')
        svg.appendChild(line)
        if (edge.label) {
          const text = document.createElementNS('http://www.w3.org/2000/svg', 'text')
          text.setAttribute('x', String((from.x + to.x) / 2))
          text.setAttribute('y', String((from.y + to.y) / 2 - 8))
          text.setAttribute('fill', muted)
          text.setAttribute('font-size', '11')
          text.setAttribute('text-anchor', 'middle')
          text.textContent = edge.label
          svg.appendChild(text)
        }
      }

      for (const node of sceneSpec.nodes) {
        const isSelected = selected === node.id
        const isCurrent = sceneSpec.steps[currentIndex] === node.id
        const group = document.createElementNS('http://www.w3.org/2000/svg', 'g')
        group.setAttribute('data-node-id', node.id)
        group.setAttribute('tabindex', '0')
        group.setAttribute('role', 'button')
        group.setAttribute('aria-label', `Select ${node.label}`)
        group.style.cursor = 'pointer'
        const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect')
        rect.setAttribute('x', String(node.x - 70))
        rect.setAttribute('y', String(node.y - 26))
        rect.setAttribute('width', '140')
        rect.setAttribute('height', '52')
        rect.setAttribute('rx', '14')
        rect.setAttribute('fill', isSelected ? accentSoft : surface)
        rect.setAttribute('stroke', isCurrent ? accent : isSelected ? good : border)
        rect.setAttribute('stroke-width', isCurrent ? '3' : isSelected ? '2' : '1')
        group.appendChild(rect)
        const dot = document.createElementNS('http://www.w3.org/2000/svg', 'circle')
        dot.setAttribute('cx', String(node.x - 51))
        dot.setAttribute('cy', String(node.y))
        dot.setAttribute('r', '5')
        dot.setAttribute('fill', node.tone === 'good' ? good : node.tone === 'warn' ? color('--art-warn', '#a86500') : node.tone === 'muted' ? muted : accent)
        group.appendChild(dot)
        const text = document.createElementNS('http://www.w3.org/2000/svg', 'text')
        text.setAttribute('x', String(node.x + 5))
        text.setAttribute('y', String(node.y + 5))
        text.setAttribute('fill', ink)
        text.setAttribute('font-size', '13')
        text.setAttribute('text-anchor', 'middle')
        text.textContent = node.label
        group.appendChild(text)
        const select = () => {
          selected = node.id
          const index = sceneSpec.steps.indexOf(node.id)
          if (index >= 0) currentIndex = index
          selectedInput.value = selected
          render()
        }
        group.addEventListener('click', select)
        group.addEventListener('keydown', event => {
          if (event.key === 'Enter' || event.key === ' ') {
            event.preventDefault()
            select()
          }
        })
        svg.appendChild(group)
      }

      const current = nodes.get(selected)
      readout.textContent = current
        ? `${current.label} · step ${currentIndex + 1}/${sceneSpec.steps.length} · ${sceneSpec.edges.filter(edge => edge.from === selected || edge.to === selected).length} connections`
        : 'Select a concept to inspect its role.'
      document.getElementById('selected-value').textContent = current?.label ?? selected
      document.getElementById('step-value').textContent = `${currentIndex + 1} / ${sceneSpec.steps.length}`
      document.getElementById('zoom-value').textContent = `${scale.toFixed(2)}×`
      parent.postMessage({ kind: 'artifact-state', state: { selected, step: currentIndex, zoom: scale, playing } }, '*')
    }

    function stepFlow() {
      currentIndex = (currentIndex + 1) % sceneSpec.steps.length
      selected = sceneSpec.steps[currentIndex]
      selectedInput.value = selected
      render()
    }

    function setPlaying(next) {
      playing = next
      playButton.textContent = playing ? 'Pause flow' : 'Play flow'
      playButton.setAttribute('aria-pressed', String(playing))
      previous = 0
      if (playing) frame = requestAnimationFrame(tick)
      else cancelAnimationFrame(frame)
      render()
    }

    function tick(now) {
      if (!playing) return
      if (previous === 0) previous = now
      if (now - previous >= 650) {
        previous = now
        stepFlow()
      }
      frame = requestAnimationFrame(tick)
    }

    function reset() {
      setPlaying(false)
      selected = sceneSpec.selected
      currentIndex = 0
      scale = sceneSpec.viewport.scale
      centerX = sceneSpec.viewport.centerX
      centerY = sceneSpec.viewport.centerY
      selectedInput.value = selected
      render()
    }

    selectedInput.addEventListener('change', () => {
      selected = selectedInput.value
      const index = sceneSpec.steps.indexOf(selected)
      if (index >= 0) currentIndex = index
      render()
    })
    document.getElementById('zoom-in').addEventListener('click', () => { scale = Math.min(4, scale * 1.25); render() })
    document.getElementById('zoom-out').addEventListener('click', () => { scale = Math.max(0.5, scale / 1.25); render() })
    document.getElementById('view-reset').addEventListener('click', reset)
    document.getElementById('reset').addEventListener('click', reset)
    document.getElementById('step').addEventListener('click', stepFlow)
    playButton.addEventListener('click', () => { setPlaying(!playing) })
    document.getElementById('confirm').addEventListener('click', () => {
      parent.postMessage({
        kind: 'artifact-action', artifactId: 'concept-flow', revision: 1,
        action: 'flow.inspected', payload: { selected, step: currentIndex, zoom: scale },
      }, '*')
    })
    svg.addEventListener('click', event => {
      const target = document.elementFromPoint(event.clientX, event.clientY)?.closest('[data-node-id]')
      if (!target) return
      selected = target.getAttribute('data-node-id')
      const index = sceneSpec.steps.indexOf(selected)
      if (index >= 0) currentIndex = index
      selectedInput.value = selected
      render()
    })
    svg.addEventListener('pointerdown', event => {
      dragging = true
      dragX = event.clientX
      dragY = event.clientY
      svg.setPointerCapture(event.pointerId)
    })
    svg.addEventListener('pointerup', () => { dragging = false })
    svg.addEventListener('pointermove', event => {
      if (!dragging) return
      centerX -= (event.clientX - dragX) / scale
      centerY -= (event.clientY - dragY) / scale
      dragX = event.clientX
      dragY = event.clientY
      render()
    })
    svg.addEventListener('wheel', event => {
      event.preventDefault()
      scale = Math.max(0.5, Math.min(4, scale * Math.exp(-event.deltaY * 0.001)))
      render()
    }, { passive: false })
    window.addEventListener('message', event => {
      if (event.source !== parent || event.data?.kind !== 'artifact-command') return
      if (event.data.command === 'play') setPlaying(true)
      else if (event.data.command === 'pause') setPlaying(false)
      else if (event.data.command === 'step') stepFlow()
      else if (event.data.command === 'reset') reset()
    })

    render()
    beat(document.querySelectorAll('.hero, .workspace, .timeline'))
  </script>
</body>
</html>
