  <script>
/* Small, one-shot motion primitives. Inline this file into an Artifact; no imports. */
function reducedMotion() {
  return window.matchMedia('(prefers-reduced-motion: reduce)').matches
}

function beat(elements, { staggerMs = 70 } = {}) {
  const list = Array.from(elements)
  if (reducedMotion()) {
    for (const element of list) element.dataset.beat = 'done'
    return
  }
  for (const [index, element] of list.entries()) {
    element.classList.add('motion-enter')
    element.style.animationDelay = `${index * staggerMs}ms`
    element.addEventListener('animationend', () => { element.dataset.beat = 'done' }, { once: true })
  }
}

function highlight(element) {
  if (!element) return
  if (reducedMotion()) return
  element.classList.remove('motion-highlight')
  void element.offsetWidth
  element.classList.add('motion-highlight')
}

function tween({ from, to, duration = 420, update, done }) {
  if (reducedMotion()) {
    update(to)
    done?.()
    return () => {}
  }
  const start = performance.now()
  let frame = 0
  const step = (now) => {
    const progress = Math.min(1, (now - start) / duration)
    const eased = 1 - Math.pow(1 - progress, 3)
    update(from + (to - from) * eased)
    if (progress < 1) frame = requestAnimationFrame(step)
    else done?.()
  }
  frame = requestAnimationFrame(step)
  return () => cancelAnimationFrame(frame)
}

</script>
  <script>
    const sceneSpec = {
      kind: 'flowchart',
      nodes: [
        { id: 'observe', label: 'Observe', x: 90, y: 70, tone: 'accent' },
        { id: 'predict', label: 'Predict', x: 320, y: 70, tone: 'accent' },
        { id: 'manipulate', label: 'Manipulate', x: 550, y: 70, tone: 'warn' },
        { id: 'feedback', label: 'Feedback', x: 550, y: 225, tone: 'good' },
        { id: 'compare', label: 'Compare', x: 320, y: 225, tone: 'good' },
        { id: 'explain', label: 'Explain', x: 90, y: 225, tone: 'muted' },
      ],
      edges: [
        { from: 'observe', to: 'predict' },
        { from: 'predict', to: 'manipulate' },
        { from: 'manipulate', to: 'feedback' },
        { from: 'feedback', to: 'compare' },
        { from: 'compare', to: 'explain' },
        { from: 'explain', to: 'observe' },
        { from: 'compare', to: 'predict', label: 'revise' },
      ],
      steps: ['observe', 'predict', 'manipulate', 'feedback', 'compare', 'explain'],
      viewport: { centerX: 0, centerY: 0, scale: 1 },
      selected: 'observe',
    }

    const svg = document.getElementById('flow')
    const readout = document.getElementById('readout')
    const selectedInput = document.getElementById('selected')
    const playButton = document.getElementById('play')
    const nodes = new Map(sceneSpec.nodes.map(node => [node.id, node]))
    let selected = sceneSpec.selected
    let currentIndex = 0
    let scale = sceneSpec.viewport.scale
    let centerX = sceneSpec.viewport.centerX
    let centerY = sceneSpec.viewport.centerY
    let playing = false
    let frame = 0
    let previous = 0
    let dragging = false
    let dragX = 0
    let dragY = 0

