    }
    selectedInput.value = selected

    function color(name, fallback) {
      return getComputedStyle(document.documentElement).getPropertyValue(name).trim() || fallback
    }

    function render() {
      const ink = color('--art-ink', '#17202b')
      const muted = color('--art-muted', '#647184')
      const accent = color('--art-accent', '#5b5bd6')
      const accentSoft = color('--art-accent-soft', 'rgba(91,91,214,.13)')
      const good = color('--art-good', '#16805c')
      const border = color('--art-border', 'rgba(68,83,112,.14)')
      const surface = color('--art-surface-raised', '#fff')
      const viewWidth = 640 / scale
      const viewHeight = 300 / scale
      svg.setAttribute('viewBox', `${320 - centerX - viewWidth / 2} ${150 - centerY - viewHeight / 2} ${viewWidth} ${viewHeight}`)
      svg.innerHTML = ''

      const defs = document.createElementNS('http://www.w3.org/2000/svg', 'defs')
      const marker = document.createElementNS('http://www.w3.org/2000/svg', 'marker')
      marker.setAttribute('id', 'arrow')
      marker.setAttribute('markerWidth', '8')
      marker.setAttribute('markerHeight', '8')
      marker.setAttribute('refX', '7')
      marker.setAttribute('refY', '3')
      marker.setAttribute('orient', 'auto')
      const arrow = document.createElementNS('http://www.w3.org/2000/svg', 'path')
      arrow.setAttribute('d', 'M0,0 L0,6 L7,3 z')
      arrow.setAttribute('fill', accent)
      marker.appendChild(arrow)
      defs.appendChild(marker)
      svg.appendChild(defs)

      for (const edge of sceneSpec.edges) {
        const from = nodes.get(edge.from)
        const to = nodes.get(edge.to)
        if (!from || !to) continue
        const active = selected === edge.from || selected === edge.to
        const line = document.createElementNS('http://www.w3.org/2000/svg', 'line')
        line.setAttribute('x1', String(from.x))
        line.setAttribute('y1', String(from.y))
        line.setAttribute('x2', String(to.x))
        line.setAttribute('y2', String(to.y))
        line.setAttribute('stroke', active ? accent : muted)
        line.setAttribute('stroke-width', active ? '3' : '1.5')
        line.setAttribute('opacity', active ? '1' : '0.48')
        line.setAttribute('marker-end', 'url(#arrow)')
        svg.appendChild(line)
        if (edge.label) {
          const text = document.createElementNS('http://www.w3.org/2000/svg', 'text')
          text.setAttribute('x', String((from.x + to.x) / 2))
          text.setAttribute('y', String((from.y + to.y) / 2 - 8))
          text.setAttribute('fill', muted)
          text.setAttribute('font-size', '11')
          text.setAttribute('text-anchor', 'middle')
          text.textContent = edge.label
          svg.appendChild(text)
        }
      }

      for (const node of sceneSpec.nodes) {
        const isSelected = selected === node.id
        const isCurrent = sceneSpec.steps[currentIndex] === node.id
        const group = document.createElementNS('http://www.w3.org/2000/svg', 'g')
        group.setAttribute('data-node-id', node.id)
        group.setAttribute('tabindex', '0')
        group.setAttribute('role', 'button')
        group.setAttribute('aria-label', `Select ${node.label}`)
        group.style.cursor = 'pointer'
        const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect')
        rect.setAttribute('x', String(node.x - 70))
        rect.setAttribute('y', String(node.y - 26))
        rect.setAttribute('width', '140')
        rect.setAttribute('height', '52')
        rect.setAttribute('rx', '14')
        rect.setAttribute('fill', isSelected ? accentSoft : surface)
        rect.setAttribute('stroke', isCurrent ? accent : isSelected ? good : border)
        rect.setAttribute('stroke-width', isCurrent ? '3' : isSelected ? '2' : '1')
        group.appendChild(rect)
        const dot = document.createElementNS('http://www.w3.org/2000/svg', 'circle')
        dot.setAttribute('cx', String(node.x - 51))
        dot.setAttribute('cy', String(node.y))
        dot.setAttribute('r', '5')
        dot.setAttribute('fill', node.tone === 'good' ? good : node.tone === 'warn' ? color('--art-warn', '#a86500') : node.tone === 'muted' ? muted : accent)
        group.appendChild(dot)
        const text = document.createElementNS('http://www.w3.org/2000/svg', 'text')
        text.setAttribute('x', String(node.x + 5))
        text.setAttribute('y', String(node.y + 5))
        text.setAttribute('fill', ink)
        text.setAttribute('font-size', '13')
        text.setAttribute('text-anchor', 'middle')
        text.textContent = node.label
        group.appendChild(text)
        const select = () => {
          selected = node.id
          const index = sceneSpec.steps.indexOf(node.id)
          if (index >= 0) currentIndex = index
          selectedInput.value = selected
          render()
        }
        group.addEventListener('click', select)
        group.addEventListener('keydown', event => {
          if (event.key === 'Enter' || event.key === ' ') {
            event.preventDefault()
            select()
          }
        })
        svg.appendChild(group)
      }

      const current = nodes.get(selected)
      readout.textContent = current
        ? `${current.label} · step ${currentIndex + 1}/${sceneSpec.steps.length} · ${sceneSpec.edges.filter(edge => edge.from === selected || edge.to === selected).length} connections`
        : 'Select a concept to inspect its role.'
      document.getElementById('selected-value').textContent = current?.label ?? selected
      document.getElementById('step-value').textContent = `${currentIndex + 1} / ${sceneSpec.steps.length}`
      document.getElementById('zoom-value').textContent = `${scale.toFixed(2)}×`
      parent.postMessage({ kind: 'artifact-state', state: { selected, step: currentIndex, zoom: scale, playing } }, '*')
    }

    function stepFlow() {
      currentIndex = (currentIndex + 1) % sceneSpec.steps.length
      selected = sceneSpec.steps[currentIndex]
      selectedInput.value = selected
      render()
    }

    function setPlaying(next) {
      playing = next
      playButton.textContent = playing ? 'Pause flow' : 'Play flow'
