      if (previous === 0) previous = now
      if (now - previous >= 650) {
        previous = now
        stepFlow()
      }
      frame = requestAnimationFrame(tick)
    }

    function reset() {
      setPlaying(false)
      selected = sceneSpec.selected
      currentIndex = 0
      scale = sceneSpec.viewport.scale
      centerX = sceneSpec.viewport.centerX
      centerY = sceneSpec.viewport.centerY
      selectedInput.value = selected
      render()
    }

    selectedInput.addEventListener('change', () => {
      selected = selectedInput.value
      const index = sceneSpec.steps.indexOf(selected)
      if (index >= 0) currentIndex = index
      render()
    })
    document.getElementById('zoom-in').addEventListener('click', () => { scale = Math.min(4, scale * 1.25); render() })
    document.getElementById('zoom-out').addEventListener('click', () => { scale = Math.max(0.5, scale / 1.25); render() })
    document.getElementById('view-reset').addEventListener('click', reset)
    document.getElementById('reset').addEventListener('click', reset)
    document.getElementById('step').addEventListener('click', stepFlow)
    playButton.addEventListener('click', () => { setPlaying(!playing) })
    document.getElementById('confirm').addEventListener('click', () => {
      parent.postMessage({
        kind: 'artifact-action', artifactId: 'concept-flow', revision: 1,
        action: 'flow.inspected', payload: { selected, step: currentIndex, zoom: scale },
      }, '*')
    })
