    svg.addEventListener('pointerdown', event => {
      dragging = true
      dragX = event.clientX
      dragY = event.clientY
      svg.setPointerCapture(event.pointerId)
    })
    svg.addEventListener('pointerup', () => { dragging = false })
    svg.addEventListener('pointermove', event => {
      if (!dragging) return
      centerX -= (event.clientX - dragX) / scale
      centerY -= (event.clientY - dragY) / scale
      dragX = event.clientX
      dragY = event.clientY
      render()
    })
